<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\Api\AuthController; use App\Http\Controllers\Api\FormsController; use App\Http\Controllers\Api\WebApiController; use App\Http\Controllers\Api\MediaController;
Route::prefix('v1/web')->group(function(){
 Route::get('pages', [WebApiController::class,'pages']); Route::get('pages/{slug}',[WebApiController::class,'page']); Route::get('news',[WebApiController::class,'news']); Route::get('team',[WebApiController::class,'team']); Route::get('board',[WebApiController::class,'board']); Route::get('sponsors',[WebApiController::class,'sponsors']); Route::get('menus/{location?}',[WebApiController::class,'menus']); Route::get('settings',[WebApiController::class,'settings']);
