 Route::middleware(['auth:sanctum','audience:web'])->group(function(){Route::post('auth/logout',[AuthController::class,'logout']);Route::get('auth/me',[AuthController::class,'me']);Route::post('auth/change-password',[AuthController::class,'changePassword']);Route::post('auth/2fa/setup',[AuthController::class,'twoFactorSetup']);Route::post('auth/2fa/confirm',[AuthController::class,'twoFactorConfirm']);Route::post('auth/2fa/disable',[AuthController::class,'twoFactorDisable']);
